  RAISE EXCEPTION 'RUNTIME_BINDING_DENIED';
 END IF;
 RETURN EXISTS(SELECT 1 FROM bill2_receipts WHERE call_id=p_call_id
  AND payload_hash=encode(sha256(convert_to(p_evidence::text,'utf8')),'hex'));
END $function$;
